-- page: livraison-et-retours (PUBLISHED)
INSERT INTO content.content (content_id, date_created, date_modified, updt_id, code, content_type, sort_order, visible, store_merchant_id, status, publish_at, unpublish_at, version, created_by, updated_by, parent_id, noindex, canonical_url, og_media_id, show_in_footer, placement, starts_at, ends_at, policy_type, meta)
VALUES (-10001, now(), now(), 'seed', 'livraison-et-retours', 'PAGE', 10, true, '65f020632bc46470c104b76f', 'PUBLISHED', null, null, 1, 'seed', 'seed', null, false, null, null, true, null, null, null, null, null)
on conflict (content_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-100001, now(), now(), 'seed', '<h2>Livraison</h2><p>Toutes les commandes passées avant 14h sont préparées le jour même dans notre atelier du 15 rue de la Paix. Nous expédions en Colissimo suivi (2 à 3 jours ouvrés) et en Chronopost 13h pour Paris intra-muros.</p><ul><li>France métropolitaine : 4,90 € — offerte dès 60 €</li><li>Union européenne : 9,90 € — offerte dès 120 €</li><li>Retrait boutique : gratuit, sous 2 heures</li></ul><h2>Retours</h2><p>Vous disposez de 30 jours pour changer d''avis. Les produits doivent être non ouverts et dans leur emballage d''origine ; les cosmétiques descellés ne peuvent être repris pour des raisons d''hygiène.</p><p>Le remboursement est effectué sous 5 jours ouvrés après réception du colis, sur le moyen de paiement d''origine.</p>', 'Livraison et retours', 'Livraison et retours', 'Délais, tarifs et conditions de retour pour toutes vos commandes en France métropolitaine et en Europe.', 'livraison, retours, colissimo, chronopost', 'Livraison et retours | Beauté Élégante Paris', 'livraison-et-retours', 'fr', -10001, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-100002, now(), now(), 'seed', '<h2>Shipping</h2><p>Orders placed before 2pm are packed the same day in our workshop at 15 rue de la Paix. We ship with tracked Colissimo (2–3 working days) and Chronopost 13h inside Paris.</p><ul><li>Mainland France: €4.90 — free over €60</li><li>European Union: €9.90 — free over €120</li><li>Boutique pickup: free, ready in 2 hours</li></ul><h2>Returns</h2><p>You have 30 days to change your mind. Items must be unopened and in their original packaging; for hygiene reasons unsealed cosmetics cannot be taken back.</p><p>Refunds are issued within 5 working days of the parcel arriving, to the original payment method.</p>', 'Shipping & returns', 'Shipping & returns', 'Delivery times, rates and return conditions for orders across France and the European Union.', 'shipping, returns, delivery, europe', 'Shipping & returns | Beauté Élégante Paris', 'shipping-and-returns', 'en', -10001, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;

-- page: nos-ingredients (PUBLISHED)
INSERT INTO content.content (content_id, date_created, date_modified, updt_id, code, content_type, sort_order, visible, store_merchant_id, status, publish_at, unpublish_at, version, created_by, updated_by, parent_id, noindex, canonical_url, og_media_id, show_in_footer, placement, starts_at, ends_at, policy_type, meta)
VALUES (-10002, now(), now(), 'seed', 'nos-ingredients', 'PAGE', 11, true, '65f020632bc46470c104b76f', 'PUBLISHED', null, null, 1, 'seed', 'seed', null, false, null, null, false, null, null, null, null, null)
on conflict (content_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-100003, now(), now(), 'seed', '<h2>Une charte, pas un argument</h2><p>Chaque formule Beauté Élégante est développée avec un laboratoire de Loire-Atlantique et validée par une évaluation toxicologique indépendante avant sa mise sur le marché.</p><h3>Ce que nous utilisons</h3><ul><li>Actifs dosés au pourcentage utile : niacinamide 5 %, acide hyaluronique 2 %, rétinal 0,05 %</li><li>Émulsions à 92 % minimum d''ingrédients d''origine naturelle</li><li>Parfums sans allergènes listés au règlement CE 1223/2009</li></ul><h3>Ce que nous excluons</h3><ul><li>Sulfates agressifs (SLS, SLES)</li><li>Silicones non biodégradables</li><li>Filtres UV controversés (oxybenzone, octinoxate)</li></ul><p>La liste INCI complète figure sur chaque fiche produit, dans l''ordre décroissant de concentration.</p>', 'Nos ingrédients', 'Nos ingrédients', 'La charte de formulation Beauté Élégante : origine naturelle, actifs dosés, listes noires et traçabilité.', 'ingrédients, clean beauty, formulation', 'Nos ingrédients | Beauté Élégante Paris', 'nos-ingredients', 'fr', -10002, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-100004, now(), now(), 'seed', '<h2>A charter, not a slogan</h2><p>Every Beauté Élégante formula is developed with a laboratory in Loire-Atlantique and cleared by an independent toxicological assessment before it goes on sale.</p><h3>What we use</h3><ul><li>Actives at a useful percentage: 5% niacinamide, 2% hyaluronic acid, 0.05% retinal</li><li>Emulsions with at least 92% ingredients of natural origin</li><li>Fragrances free of the allergens listed in EC regulation 1223/2009</li></ul><h3>What we leave out</h3><ul><li>Harsh sulfates (SLS, SLES)</li><li>Non-biodegradable silicones</li><li>Contested UV filters (oxybenzone, octinoxate)</li></ul><p>The full INCI list is on every product page, in descending order of concentration.</p>', 'Our ingredients', 'Our ingredients', 'The Beauté Élégante formulation charter: natural origin, active percentages, blacklists and traceability.', 'ingredients, clean beauty, formulation', 'Our ingredients | Beauté Élégante Paris', 'our-ingredients', 'en', -10002, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;

