INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-100005, now(), now(), 'seed', '<h2>Travailler chez Beauté Élégante</h2><p>Nous sommes vingt-quatre, entre la boutique du 2e arrondissement, l''atelier de préparation et une petite équipe produit.</p><h3>Postes ouverts</h3><ul><li>Conseiller·ère beauté — CDI, Paris 2e</li><li>Chargé·e de formulation — CDI, Nantes</li><li>Alternance e-commerce — 12 mois, Paris</li></ul><p>Écrivez à <a href="mailto:recrutement@beaute-elegante.fr">recrutement@beaute-elegante.fr</a> en nous disant surtout pourquoi ce métier-là.</p>', 'Carrières', 'Carrières', 'Postes ouverts en boutique, à l''atelier et au siège parisien.', 'emploi, recrutement, carrière', 'Carrières | Beauté Élégante Paris', 'carrieres', 'fr', -10003, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-100006, now(), now(), 'seed', '<h2>Working at Beauté Élégante</h2><p>There are twenty-four of us, between the boutique in the 2nd arrondissement, the packing workshop and a small product team.</p><h3>Open roles</h3><ul><li>Beauty advisor — permanent, Paris 2e</li><li>Formulation lead — permanent, Nantes</li><li>E-commerce apprentice — 12 months, Paris</li></ul><p>Write to <a href="mailto:recrutement@beaute-elegante.fr">recrutement@beaute-elegante.fr</a> and tell us, above all, why this particular craft.</p>', 'Careers', 'Careers', 'Open roles in the boutique, the workshop and the Paris head office.', 'jobs, hiring, careers', 'Careers | Beauté Élégante Paris', 'careers', 'en', -10003, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;

