INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-100007, now(), now(), 'seed', '<h2>Espace presse</h2><p>Cette page est rattachée à « À propos » : elle sert aussi à vérifier le fil d''Ariane du storefront, qui doit afficher Accueil › À propos › Espace presse.</p><p>Contact : Claire Bouvier — <a href="mailto:presse@beaute-elegante.fr">presse@beaute-elegante.fr</a> — +33 1 23 45 67 90.</p><h3>Derniers communiqués</h3><ul><li>Ouverture de l''atelier de Nantes — mars 2026</li><li>Recharges verre consignées pour toute la gamme soin — janvier 2026</li></ul>', 'Espace presse', 'Espace presse', 'Communiqués, visuels haute définition et contacts presse.', 'presse, média, communiqué', 'Espace presse | Beauté Élégante Paris', 'presse', 'fr', -10004, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-100008, now(), now(), 'seed', '<h2>Press room</h2><p>This page hangs off “About us”, which also makes it the check on the storefront breadcrumb: it should read Home › About us › Press room.</p><p>Contact: Claire Bouvier — <a href="mailto:presse@beaute-elegante.fr">presse@beaute-elegante.fr</a> — +33 1 23 45 67 90.</p><h3>Recent releases</h3><ul><li>The Nantes workshop opens — March 2026</li><li>Returnable glass refills across the skincare range — January 2026</li></ul>', 'Press room', 'Press room', 'Press releases, high-resolution imagery and media contacts.', 'press, media, releases', 'Press room | Beauté Élégante Paris', 'press-room', 'en', -10004, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;

