INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-100009, now(), now(), 'seed', '<h2>Offrir le bon geste</h2><p>Nos cartes cadeaux existent de 25 à 250 €, en version numérique envoyée immédiatement ou en carte imprimée sur papier Munken, glissée dans un étui toilé.</p><p>Elles sont valables deux ans, utilisables en ligne comme en boutique, et le solde restant est conservé.</p><p>Cette page porte une URL canonique et une image Open Graph : de quoi vérifier le rendu SEO du storefront.</p>', 'Cartes cadeaux', 'Cartes cadeaux', 'Cartes cadeaux de 25 à 250 €, valables deux ans en ligne et en boutique.', 'carte cadeau, bon d''achat', 'Cartes cadeaux | Beauté Élégante Paris', 'cartes-cadeaux', 'fr', -10005, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-100010, now(), now(), 'seed', '<h2>The right gesture, wrapped</h2><p>Our gift cards run from €25 to €250, either digital and sent straight away or printed on Munken paper and slipped into a cloth sleeve.</p><p>They are valid for two years, usable online and in the boutique, and any remaining balance is kept.</p><p>This page carries a canonical URL and an Open Graph image, which makes it the check on the storefront''s SEO rendering.</p>', 'Gift cards', 'Gift cards', 'Gift cards from €25 to €250, valid for two years online and in the boutique.', 'gift card, voucher', 'Gift cards | Beauté Élégante Paris', 'gift-cards', 'en', -10005, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;

