INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-100011, now(), now(), 'seed', '<h2>Ce que nous mesurons</h2><p>Cette page est marquée <code>noindex</code> : elle doit s''afficher normalement dans la boutique mais sortir du sitemap. C''est le contrôle du drapeau SEO.</p><ul><li>78 % de la gamme soin disponible en recharge</li><li>Consigne verre remboursée 3 € en boutique</li><li>Livraison neutre en carbone via compensation Colissimo</li></ul>', 'Engagement durable', 'Engagement durable', 'Recharges, consigne verre et empreinte carbone — page volontairement exclue de l''indexation.', 'durable, recharge, consigne', 'Engagement durable | Beauté Élégante Paris', 'engagement-durable', 'fr', -10006, 'TRANSLATED', null, null, null, null)
