INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-100012, now(), now(), 'seed', '<h2>What we measure</h2><p>This page is flagged <code>noindex</code>: it should render normally in the storefront but stay out of the sitemap. That is the check on the SEO flag.</p><ul><li>78% of the skincare range available as a refill</li><li>€3 back in the boutique on returned glass</li><li>Carbon-neutral delivery through Colissimo offsetting</li></ul>', 'Sustainability', 'Sustainability', 'Refills, glass deposit and carbon footprint — a page deliberately kept out of the index.', 'sustainability, refill, deposit', 'Sustainability | Beauté Élégante Paris', 'sustainability', 'en', -10006, 'TRANSLATED', null, null, null, null)
